sys_script_client.script:
function onSubmit() {

  if (g_form._om_cap_inflight) return false;
  if (g_form._om_cap_allow === true) { g_form._om_cap_allow = false; return true; }

  var baseId = g_form.getValue('base');
  if (!baseId) return true;

  g_form._om_cap_inflight = true;

  var action = (g_form.getActionName && g_form.getActionName()) || '';

  var ga = new GlideAjax('x_1834930_office_0.BaseRegistrationGuard');
  ga.addParam('sysparm_name', 'isBaseFull');
  ga.addParam('sysparm_base_id', baseId);

  ga.addParam('sysparm_exclude_id', g_form.getUniqueValue() || '');

  ga.getXMLAnswer(function(answer) {
    g_form._om_cap_inflight = false;

    var res = {};
    try { res = JSON.parse(answer || '{}'); } catch (e) {
      var err = 'Could not validate base capacity. Please try again.';
      g_form.addErrorMessage(err);
      alert(err);
      return;
    }

    if (res.ok === false) {
      var msg = 'This base has reached its maximum capacity.';
      if (typeof res.count !== 'undefined' && typeof res.capacity !== 'undefined')
        msg = 'This base has reached its maximum capacity (' + res.count + '/' + res.capacity + ').';
      g_form.addErrorMessage(msg);
      alert(msg);
      return;
    }

    g_form._om_cap_allow = true;

    if (typeof g_form.submit === 'function') {

      try { action ? g_form.submit(action) : g_form.submit(); return; } catch (e) {}
    }
    if (typeof window.gsftSubmit === 'function') {
      try { gsftSubmit(null, g_form.getFormElement(), action || 'sysverb_update'); return; } catch (e) {}
    }

    g_form.getFormElement().submit();
  });

  return false;
}
